  exports.Set("isLibExist", Napi::Function::New(env, isLibExist));
  exports.Set("getLibPath", Napi::Function::New(env, getLibPath));
  exports.Set("verifyTrust", Napi::Function::New(env, verifyTrust));
  return exports;
}

